    if type(records) is not list or type(boundaries) is not list:
        return part(facts, negatives, witnesses, False, reasons + ['explicit_legal_channel_unread'])
    bases = {'s151_b':'section151_b_exact','s151_b_applies':'section151_b_applies_exact','s151_c_applies':'section151_c_applies_exact','s152_c_1':'section152_c_1_exact','s63_f_1_A':'section63_f_1_A_exact','s63_f_1_B':'section63_f_1_B_exact'}
    relations = {'s151_b':'taxpayer_personal_exemption_amount','s151_b_applies':'spouse_personal_exemption_entitlement','s151_c_applies':'dependent_personal_exemption_entitlement','s152_c_1':'qualifying_child_status','s63_f_1_A':'aged_taxpayer_additional_amount','s63_f_1_B':'aged_spouse_additional_amount'}
    markers = {'s151_b':'151(b)','s151_b_applies':'151(b)','s151_c_applies':'151(c)','s152_c_1':'152(c)(1)','s63_f_1_A':'63(f)(1)(a)','s63_f_1_B':'63(f)(1)(b)'}
    seen = set()
    for record in records:
        evidence = checked(record, public, True)
        name = record.get('predicate')
        args = record.get('arguments')
        polarity = record.get('polarity')
        if evidence is None or not valid_given(name, args) or polarity not in ('positive','negative') or record.get('basis') != bases.get(name) or record.get('source_relation') != relations.get(name):
            complete = False
            continue
        quote = ' '.join([row['quote'].lower() for row in evidence]).replace('section','').replace('§','').replace(' ','')
        if markers.get(name) not in quote:
